// Night 4 — the top floor. Reads night-3 flags (has_key, tracker, denis_call, leo_followed, sal_cut, rick_found, dana_safe).
// Sets: went_up, met_denis, denis_ally | denis_stays, took_photos, stayed_down, reyes_side | man_side.
// Local (read only inside this night): marv_stairs, leo_bell.
NIGHTS.push({
  id: 4,
  title: { en: 'Night four', ru: 'Ночь четвёртая', uk: 'Ніч четверта', es: 'Cuarta noche' },
  scenes: [
    {
      time: '23:00', name: { en: 'The drawer', ru: 'Ящик стола', uk: 'Шухляда', es: 'El cajón' }, voice: { gender: 'm', pitch: 0.75, rate: 0.92 },
      portrait: objectPortrait('#3a2a1a', '—'), start: 'a',
      nodes: {
        a: { who: 'narr',
             // Night 4 starts clean: nothing from this night can be true before it begins.
             effect: { flags: { went_up: false, met_denis: false, denis_ally: false, denis_stays: false, took_photos: false, stayed_down: false, reyes_side: false, man_side: false, marv_stairs: false, leo_bell: false } },
             text: (s) => s.flags.has_key
              ? { en: "Fourth night. The rain is back. Under the register cards: a brass key, tag 12. Sal's note on top of it: 'Top floor is storage. It stays storage.'", ru: 'Четвёртая ночь. Дождь вернулся. Под карточками постояльцев: латунный ключ, бирка 12. Сверху записка от Сэла: «Верхний этаж — кладовка. Кладовкой и останется».', uk: 'Четверта ніч. Дощ повернувся. Під картками постояльців: латунний ключ, бирка 12. Зверху записка від Села: «Верхній поверх — комора. Коморою й лишиться».', es: 'Cuarta noche. Ha vuelto la lluvia. Bajo las fichas de registro: una llave de latón, chapa 12. Encima, una nota de Sal: «El último piso es un trastero. Y trastero se queda».' }
              : { en: "Fourth night. The rain is back. The drawer holds register cards and nothing with a number on it. Sal's note: 'Top floor is storage. It stays storage.'", ru: 'Четвёртая ночь. Дождь вернулся. В ящике карточки постояльцев и ничего с номером. Записка от Сэла: «Верхний этаж — кладовка. Кладовкой и останется».', uk: 'Четверта ніч. Дощ повернувся. У шухляді картки постояльців і нічого з номером. Записка від Села: «Верхній поверх — комора. Коморою й лишиться».', es: 'Cuarta noche. Ha vuelto la lluvia. En el cajón hay fichas de registro y nada con un número. Nota de Sal: «El último piso es un trastero. Y trastero se queda».' },
             next: (s) => (s.flags.denis_call ? 'thu' : s.flags.envelope ? 'env' : 'end') },
        thu: { who: 'narr', text: (s) => s.flags.thursday
              ? { en: "'After Friday it's just brass.' Denis said that last night, at three, because you asked. Tomorrow is Friday.", ru: '«После пятницы это просто латунь». Денис сказал это вчера, в три, потому что вы спросили. Завтра пятница.', uk: '«Після п’ятниці це просто латунь». Денис сказав це вчора, о третій, бо ви спитали. Завтра п’ятниця.', es: '«Después del viernes, es solo latón». Denis lo dijo anoche, a las tres, porque usted preguntó. Mañana es viernes.' }
              : { en: "'Don't come up. …Or come up before Friday.' That was last night, at three. Tomorrow is Friday.", ru: '«Не поднимайтесь. …Или поднимитесь до пятницы». Это было вчера, в три. Завтра пятница.', uk: '«Не підіймайтеся. …Або підійміться до п’ятниці». Це було вчора, о третій. Завтра п’ятниця.', es: '«No suba. …O suba antes del viernes». Eso fue anoche, a las tres. Mañana es viernes.' },
               next: (s) => (s.flags.envelope ? 'env' : 'end') },
        env: { who: 'narr', text: { en: 'The envelope is in there too. You have stopped weighing it.', ru: 'Конверт тоже там. Вы перестали его взвешивать.', uk: 'Конверт теж там. Ви перестали його зважувати.', es: 'El sobre también está ahí. Usted ha dejado de sopesarlo.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Marv, room 7', ru: 'Марв, номер 7', uk: 'Марв, номер 7', es: 'Marv, habitación 7' }, voice: { gender: 'm', pitch: 0.85, rate: 0.9 },
      portrait: portrait('#4a5a6a', false, false), start: 'a',
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.paid_marv ? { flags: { marv_thanked: true } } : {}), text: (s) => ((t) => (s.flags.paid_marv && !s.flags.marv_thanked ? { en: "Somebody paid my week. Sal says it wasn't him. …Thank you. Don't say anything. " + t.en, ru: "Кто-то оплатил мою неделю. Сэл говорит, не он. …Спасибо. Ничего не говорите. " + t.ru, uk: "Хтось оплатив мій тиждень. Сел каже, не він. …Дякую. Нічого не кажіть. " + t.uk, es: "Alguien me pagó la semana. Sal dice que no fue él. …Gracias. No diga nada. " + t.es } : t))(s.flags.leo_followed
              ? { en: "The kid says the man goes up, not out. I've been saying that for a year. Nobody listens to a tenant.", ru: 'Парень говорит, мужчина идёт наверх, а не на улицу. Я год это твержу. Жильца никто не слушает.', uk: 'Хлопець каже, чоловік іде нагору, а не на вулицю. Я рік це кажу. Мешканця ніхто не слухає.', es: 'El chico dice que el hombre sube, no sale. Llevo un año diciéndolo. Nadie le hace caso a un inquilino.' }
              : s.flags.marv_told
              ? { en: "The light on the top floor was on at four this morning. It hasn't been on since Denis.", ru: 'Свет на верхнем этаже горел в четыре утра. Он не горел с тех пор, как ушёл Денис.', uk: 'Світло на верхньому поверсі горіло о четвертій ранку. Воно не горіло відтоді, як пішов Денис.', es: 'La luz del último piso estaba encendida a las cuatro de esta mañana. No se encendía desde lo de Denis.' }
              : { en: "The light on the top floor was on at four this morning. Twenty years I've lived here. It's never on.", ru: 'Свет на верхнем этаже горел в четыре утра. Двадцать лет здесь живу. Он никогда не горит.', uk: 'Світло на верхньому поверсі горіло о четвертій ранку. Двадцять років тут живу. Воно ніколи не горить.', es: 'La luz del último piso estaba encendida a las cuatro de esta mañana. Veinte años viviendo aquí. Nunca está encendida.' }),
             choices: [
               { text: { en: '"Who lives up there, Marv?"', ru: '«Кто там живёт, Марв?»', uk: '«Хто там живе, Марве?»', es: '«¿Quién vive ahí arriba, Marv?»' }, next: 'who' },
               { text: { en: '"Would you sit by the stairs tonight? Just sit."', ru: '«Посидишь сегодня у лестницы? Просто посидишь».', uk: '«Посидиш сьогодні біля сходів? Просто посидиш».', es: '«¿Te sentarías junto a la escalera esta noche? Solo sentarte».' }, next: 'sit', effect: { flags: { marv_stairs: true } } },
               { text: { en: '"Go to bed, Marv."', ru: '«Иди спать, Марв».', uk: '«Іди спати, Марве».', es: '«Vete a dormir, Marv».' }, next: 'bed' },
             ] },
        who: { who: 'guest', text: { en: "Nobody. Officially. Sal says storage. Storage doesn't put a kettle on at four in the morning.", ru: 'Никто. Официально. Сэл говорит, кладовка. Кладовка не ставит чайник в четыре утра.', uk: 'Ніхто. Офіційно. Сел каже, комора. Комора не ставить чайник о четвертій ранку.', es: 'Nadie. Oficialmente. Sal dice que es un trastero. Un trastero no pone la tetera a las cuatro de la mañana.' }, next: 'who2' },
        who2: { who: 'narr', text: (s) => s.flags.has_key
              ? { en: 'He looks at your hand. The one that has been in your pocket all evening.', ru: 'Он смотрит на вашу руку. Ту, что весь вечер в кармане.', uk: 'Він дивиться на вашу руку. Ту, що весь вечір у кишені.', es: 'Mira su mano. La que ha tenido en el bolsillo toda la noche.' }
              : { en: 'He looks at the stairs the way other people look at a clock.', ru: 'Он смотрит на лестницу так, как другие смотрят на часы.', uk: 'Він дивиться на сходи так, як інші дивляться на годинник.', es: 'Mira la escalera como otros miran un reloj.' },
               next: 'end' },
        sit: { who: 'guest', text: { en: "Sit. I can sit. I've been sitting twenty years, might as well do it somewhere useful.", ru: 'Посидеть. Это я могу. Двадцать лет сижу, могу и там, где от этого есть толк.', uk: 'Посидіти. Це я можу. Двадцять років сиджу, можу й там, де з цього є користь.', es: 'Sentarme. Eso sé hacerlo. Llevo veinte años sentado; ya puestos, que sea en algún sitio útil.' }, next: 'end' },
        bed: { who: 'guest', text: { en: "Right. …If you go up, count the flights. There's four. Everyone says three.", ru: 'Ладно. …Если пойдёте наверх, считайте пролёты. Их четыре. Все говорят, три.', uk: 'Гаразд. …Якщо підете нагору, рахуйте прольоти. Їх чотири. Усі кажуть, три.', es: 'Bueno. …Si sube, cuente los tramos. Son cuatro. Todo el mundo dice tres.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Leo', ru: 'Лео', uk: 'Лео', es: 'Leo' }, voice: { gender: 'm', pitch: 1.3, rate: 1.15 },
      portrait: portrait('#6a5a2a', true, false), start: 'a',
      when: (s) => s.flags.leo_friend || s.flags.leo_watch || s.flags.leo_followed,
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.leo_money ? { flags: { leo_thanked: true } } : {}), text: (s) => ((t) => (s.flags.leo_money && !s.flags.leo_thanked ? { en: "Somebody left fifty at the shelter. Envelope, my name on it. Nobody writes my name. …I carried it around an hour before I opened it. This hotel's rubbing off on me. " + t.en, ru: "Кто-то оставил в приюте пятьдесят. Конверт, на нём моё имя. Моё имя никто не пишет. …Я час носил его, прежде чем открыть. Ваш отель на меня плохо влияет. " + t.ru, uk: "Хтось залишив у притулку п’ятдесят. Конверт, на ньому моє ім’я. Моє ім’я ніхто не пише. …Я годину носив його, перш ніж відкрити. Ваш готель на мене погано впливає. " + t.uk, es: "Alguien dejó cincuenta en el albergue. Un sobre, con mi nombre. Nadie escribe mi nombre. …Lo llevé encima una hora antes de abrirlo. Este hotel se me está pegando. " + t.es } : t))(s.flags.leo_followed
              ? { en: "I went where he went. Back stairs, past the third floor. There's a fourth. There's a door. He knocked like he lived there.", ru: 'Я пошёл за ним. Чёрная лестница, мимо третьего этажа. Есть четвёртый. Есть дверь. Он постучал так, будто там живёт.', uk: 'Я пішов за ним. Чорні сходи, повз третій поверх. Є четвертий. Є двері. Він постукав так, ніби там живе.', es: 'Fui adonde fue él. Escalera de servicio, más allá del tercer piso. Hay un cuarto piso. Hay una puerta. Llamó como si viviera allí.' }
              : { en: "Shelter's got a curfew. I'm breaking it. Something's wrong with this place at night and you're the only one not pretending.", ru: 'В приюте комендантский час. Я его нарушаю. С этим местом ночью что-то не так, и только вы не делаете вид.', uk: 'У притулку комендантська година. Я її порушую. З цим місцем уночі щось не так, і тільки ви не вдаєте.', es: 'El albergue tiene toque de queda. Me lo estoy saltando. A este sitio le pasa algo de noche, y usted es {el único|la única} que no finge.' }),
             choices: [
               { text: { en: '"Watch the front door at three. If he comes in, ring the bell twice."', ru: '«Следи за входом в три. Если он войдёт, позвони в звонок дважды».', uk: '«Стеж за входом о третій. Якщо він зайде, подзвони у дзвінок двічі».', es: '«Vigila la puerta de entrada a las tres. Si entra él, toca el timbre dos veces».' }, next: 'watch', effect: { flags: { leo_bell: true } } },
               { text: { en: '"Back to the shelter. Tonight isn\'t yours."', ru: '«Возвращайся в приют. Эта ночь не твоя».', uk: '«Повертайся в притулок. Ця ніч не твоя».', es: '«Vuelve al albergue. Esta noche no es tuya».' }, next: 'shelter' },
               { text: { en: '"Take twenty. Get a cab. Don\'t come back this week."', ru: '«Возьми двадцать. Возьми такси. На этой неделе не возвращайся».', uk: '«Візьми двадцять. Візьми таксі. Цього тижня не повертайся».', es: '«Toma veinte. Pide un taxi. No vuelvas esta semana».' }, next: 'cab', effect: { cash: -20 } },
             ] },
        watch: { who: 'guest', text: { en: "Twice. Got it. …If it's more than him, how many rings?", ru: 'Дважды. Понял. …А если их больше, чем он один, сколько раз звонить?', uk: 'Двічі. Зрозумів. …А якщо їх більше, ніж він один, скільки разів дзвонити?', es: 'Dos veces. Entendido. …¿Y si viene más gente que él, cuántas veces?' }, next: 'watch2' },
        watch2: { who: 'narr', text: { en: 'You do not have an answer. He nods like that was one.', ru: 'У вас нет ответа. Он кивает так, будто это и был ответ.', uk: 'У вас немає відповіді. Він киває так, ніби це і була відповідь.', es: 'Usted no tiene respuesta. Él asiente como si esa fuera la respuesta.' }, next: 'end' },
        shelter: { who: 'guest', text: { en: "You sound like the cop. …Okay. But if the light's on when I walk past, I'm coming back.", ru: 'Вы говорите как та полицейская. …Ладно. Но если свет будет гореть, когда я буду проходить мимо, я вернусь.', uk: 'Ви говорите як та поліцейська. …Гаразд. Але якщо світло горітиме, коли я проходитиму повз, я повернуся.', es: 'Habla igual que la agente. …Está bien. Pero si la luz está encendida cuando pase por delante, vuelvo.' }, next: 'end' },
        cab: { who: 'narr', text: { en: "He takes the twenty like it weighs more than twenty. At the door: 'You're the first adult who ever paid me to be safe.'", ru: 'Он берёт двадцатку так, будто она весит больше двадцати. У двери: «Мне ещё никто из взрослых не платил за то, чтобы я был в безопасности».', uk: 'Він бере двадцятку так, ніби вона важить більше за двадцять. Біля дверей: «Мені ще ніхто з дорослих не платив за те, щоб я був у безпеці».', es: 'Toma los veinte como si pesaran más de veinte. En la puerta: «Es {el primer adulto|la primera adulta} que me paga por estar a salvo».' }, next: 'end' },
      }
    },
    {
      name: { en: 'Dana', ru: 'Дана', uk: 'Дана', es: 'Dana' }, voice: { gender: 'f', pitch: 1.05, rate: 1.0 },
      portrait: portrait('#8a3a5a', false, false), start: 'a',
      when: (s) => s.flags.dana_stays,
      nodes: {
        a: { who: 'guest', effect: (s) => (s.flags.dana_money ? { flags: { dana_thanked: true } } : {}), text: (s) => ((t) => (s.flags.dana_money && !s.flags.dana_thanked ? { en: "There were eighty dollars under my door. No note. I'm not going to ask. …Thank you. " + t.en, ru: "Под дверью лежали восемьдесят долларов. Без записки. Я не буду спрашивать. …Спасибо. " + t.ru, uk: "Під дверима лежало вісімдесят доларів. Без записки. Я не питатиму. …Дякую. " + t.uk, es: "Había ochenta dólares bajo mi puerta. Sin nota. No voy a preguntar. …Gracias. " + t.es } : t))(s.flags.rick_found
              ? { en: "He found the room. Knocked for an hour. Marv came out with a broom, if you can believe it. I'm leaving before he comes back. Is there a way out that isn't the front?", ru: 'Он нашёл номер. Стучал час. Марв вышел со шваброй, представляете. Я уезжаю, пока он не вернулся. Есть выход не через парадную?', uk: 'Він знайшов номер. Стукав годину. Марв вийшов зі шваброю, уявляєте. Я їду, поки він не повернувся. Є вихід не через парадні двері?', es: 'Encontró la habitación. Estuvo una hora golpeando la puerta. Marv salió con una escoba, fíjese. Me voy antes de que vuelva. ¿Hay alguna salida que no sea la de delante?' }
              : { en: "Fourth night. He hasn't found me. I'm starting to sleep. …You look worse than I do, clerk. What's upstairs?", ru: 'Четвёртая ночь. Он меня не нашёл. Я начинаю спать. …Вы выглядите хуже меня, портье. Что там наверху?', uk: 'Четверта ніч. Він мене не знайшов. Я починаю спати. …Ви виглядаєте гірше за мене, портьє. Що там нагорі?', es: 'Cuarta noche. No me ha encontrado. Empiezo a dormir. …Tiene peor cara que yo, recepcionista. ¿Qué hay arriba?' }),
             choices: (s) => s.flags.rick_found
              ? [
                  { text: { en: '"Back door, through the kitchen. Cab\'s on the hotel. Go."', ru: '«Чёрный ход, через кухню. Такси за счёт отеля. Идите».', uk: '«Чорний хід, через кухню. Таксі коштом готелю. Ідіть».', es: '«Puerta de atrás, por la cocina. El taxi lo paga el hotel. Váyase».' }, next: 'cab', effect: { cash: -40 } },
                  { text: { en: '"Room 11, under Marv\'s name. He\'ll never look for a Marv."', ru: '«Номер 11, на имя Марва. Марва он искать не станет».', uk: '«Номер 11, на ім’я Марва. Марва він шукати не буде».', es: '«Habitación 11, a nombre de Marv. Nunca buscará a un Marv».' }, next: 'eleven' },
                  { text: { en: '"If he comes back, I can\'t hold him."', ru: '«Если он вернётся, я его не удержу».', uk: '«Якщо він повернеться, я його не втримаю».', es: '«Si vuelve, no podré detenerlo».' }, next: 'honest' },
                ]
              : [
                  { text: { en: '"Storage."', ru: '«Кладовка».', uk: '«Комора».', es: '«Un trastero».' }, next: 'storage' },
                  { text: { en: '"I don\'t know yet. I\'m going to find out."', ru: '«Пока не знаю. Собираюсь выяснить».', uk: '«Поки не знаю. Збираюся з’ясувати».', es: '«Todavía no lo sé. Voy a averiguarlo».' }, next: 'find' },
                  { text: { en: '"Whatever it is, it isn\'t coming to room 4. Sleep."', ru: '«Что бы там ни было, в четвёртый оно не придёт. Спите».', uk: '«Хай що там є, у четвертий воно не прийде. Спіть».', es: '«Sea lo que sea, no va a llegar a la habitación 4. Duerma».' }, next: 'sleep' },
                ] },
        cab: { who: 'narr', text: { en: "She goes out the way the rubbish goes out. She does not look back. It is the first time you have seen her not look back.", ru: 'Она уходит той дорогой, которой выносят мусор. Не оглядывается. Вы впервые видите, что она не оглядывается.', uk: 'Вона йде тією дорогою, якою виносять сміття. Не озирається. Ви вперше бачите, що вона не озирається.', es: 'Sale por donde sale la basura. No mira atrás. Es la primera vez que usted la ve no mirar atrás.' }, next: 'end' },
        eleven: { who: 'guest', text: { en: "Marv. …He'd like that. Tell him I'll bring the broom back.", ru: 'Марв. …Ему бы понравилось. Скажите ему, что швабру я верну.', uk: 'Марв. …Йому б сподобалося. Скажіть йому, що швабру я поверну.', es: 'Marv. …Le gustaría. Dígale que le devolveré la escoba.' }, next: 'end' },
        honest: { who: 'guest', text: { en: "I know. I'm not asking you to. I'm asking you to look up from the desk when he comes in. That's all anyone ever had to do.", ru: 'Знаю. Я и не прошу. Я прошу поднять глаза от стойки, когда он войдёт. Больше ни от кого никогда и не требовалось.', uk: 'Знаю. Я й не прошу. Я прошу підвести очі від стійки, коли він зайде. Більше ні від кого ніколи й не вимагалося.', es: 'Lo sé. No se lo pido. Le pido que levante la vista del mostrador cuando él entre. Nunca hizo falta más que eso.' }, next: 'end' },
        storage: { who: 'guest', text: { en: "Storage. …I lived with a man who said 'nothing' like that. Good night, clerk.", ru: 'Кладовка. …Я жила с человеком, который так говорил «ничего». Спокойной ночи, портье.', uk: 'Комора. …Я жила з чоловіком, який так казав «нічого». Добраніч, портьє.', es: 'Un trastero. …Viví con un hombre que decía «nada» así. Buenas noches, recepcionista.' }, next: 'end' },
        find: { who: 'guest', text: { en: "Then find out with the door open behind you. That's the only advice I have, and I paid for it.", ru: 'Тогда выясняйте так, чтобы дверь за спиной была открыта. Это единственный мой совет, и я за него дорого заплатила.', uk: 'Тоді з’ясовуйте так, щоб двері за спиною були відчинені. Це єдина моя порада, і я за неї дорого заплатила.', es: 'Entonces averígüelo con la puerta abierta a su espalda. Es el único consejo que tengo, y lo pagué caro.' }, next: 'end' },
        sleep: { who: 'guest', text: { en: "I'll sleep. You won't. That's the deal, I suppose.", ru: 'Я буду спать. Вы — нет. Такой, видимо, уговор.', uk: 'Я спатиму. Ви — ні. Така, мабуть, домовленість.', es: 'Yo dormiré. Usted no. Supongo que ese es el trato.' }, next: 'end' },
      }
    },
    {
      time: '01:30', name: { en: 'The door upstairs', ru: 'Дверь наверху', uk: 'Двері нагорі', es: 'La puerta de arriba' }, voice: { gender: 'm', pitch: 0.75, rate: 0.92 },
      portrait: objectPortrait('#1a1a2a', '12'), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.has_key
              ? { en: '01:30. The key has been warm in your pocket all night. Four flights up, a door with no number, and light under it.', ru: '01:30. Ключ весь вечер греется в кармане. Четыре пролёта вверх, дверь без номера, и под ней свет.', uk: '01:30. Ключ весь вечір гріється в кишені. Чотири прольоти вгору, двері без номера, і під ними світло.', es: '01:30. La llave lleva toda la noche caliente en su bolsillo. Cuatro tramos más arriba, una puerta sin número, y luz por debajo.' }
              : { en: '01:30. You have no key. You climb anyway. Four flights, a door with no number, a peephole painted over from the inside. Light under it.', ru: '01:30. Ключа у вас нет. Вы всё равно поднимаетесь. Четыре пролёта, дверь без номера, глазок закрашен изнутри. Под ней свет.', uk: '01:30. Ключа у вас немає. Ви все одно підіймаєтеся. Чотири прольоти, двері без номера, вічко зафарбоване зсередини. Під ними світло.', es: '01:30. No tiene llave. Sube de todos modos. Cuatro tramos, una puerta sin número, una mirilla pintada por dentro. Luz por debajo.' },
             choices: (s) => s.flags.has_key
              ? [
                  { text: { en: 'Go up. Use the key.', ru: 'Подняться. Открыть ключом.', uk: 'Піднятися. Відчинити ключем.', es: 'Subir. Usar la llave.' }, next: 'up', effect: { flags: { went_up: true } } },
                  { text: { en: 'Go up. Only to look at the door.', ru: 'Подняться. Только посмотреть на дверь.', uk: 'Піднятися. Лише подивитися на двері.', es: 'Subir. Solo para mirar la puerta.' }, next: 'look' },
                  { text: { en: 'Put the key back under the register cards. Not tonight.', ru: 'Убрать ключ обратно под карточки. Не сегодня.', uk: 'Покласти ключ назад під картки. Не сьогодні.', es: 'Devolver la llave bajo las fichas de registro. Esta noche no.' }, next: 'down', effect: { flags: { stayed_down: true } } },
                ]
              : [
                  { text: { en: 'Knock.', ru: 'Постучать.', uk: 'Постукати.', es: 'Llamar a la puerta.' }, next: 'knock' },
                  { text: { en: 'Listen.', ru: 'Прислушаться.', uk: 'Прислухатися.', es: 'Escuchar.' }, next: 'listen' },
                  { text: { en: 'Go back down. There is no room twelve.', ru: 'Спуститься. Двенадцатого номера нет.', uk: 'Спуститися. Дванадцятого номера немає.', es: 'Volver abajo. No hay habitación doce.' }, next: 'back' },
                ] },
        up: { who: 'narr', text: { en: 'The light under the door goes out as you reach it, then comes back. Like a breath. The key turns before you finish turning it.', ru: 'Свет под дверью гаснет, когда вы подходите, и загорается снова. Как вдох. Ключ поворачивается раньше, чем вы его довернули.', uk: 'Світло під дверима гасне, коли ви підходите, і загоряється знову. Як вдих. Ключ повертається раніше, ніж ви його довернули.', es: 'La luz bajo la puerta se apaga cuando usted llega, y vuelve. Como una respiración. La llave gira antes de que usted termine de girarla.' }, next: 'end' },
        look: { who: 'narr', text: { en: 'The peephole is painted over from the inside. Someone in there does not want to see the stairs. The key is very small in your hand.', ru: 'Глазок закрашен изнутри. Кто-то там не хочет видеть лестницу. Ключ в вашей руке совсем маленький.', uk: 'Вічко зафарбоване зсередини. Хтось там не хоче бачити сходи. Ключ у вашій руці зовсім маленький.', es: 'La mirilla está pintada por dentro. Alguien ahí dentro no quiere ver la escalera. La llave parece muy pequeña en su mano.' },
                choices: [
                  { text: { en: 'Use it.', ru: 'Открыть.', uk: 'Відчинити.', es: 'Usarla.' }, next: 'up', effect: { flags: { went_up: true } } },
                  { text: { en: 'Back down.', ru: 'Вниз.', uk: 'Униз.', es: 'Volver abajo.' }, next: 'down', effect: { flags: { stayed_down: true } } },
                ] },
        down: { who: 'narr', text: { en: 'You put the key back under the register cards. It is not a decision. It is a postponement. The lamp hums.', ru: 'Вы кладёте ключ обратно под карточки. Это не решение. Это отсрочка. Лампа гудит.', uk: 'Ви кладете ключ назад під картки. Це не рішення. Це відстрочка. Лампа гуде.', es: 'Devuelve la llave bajo las fichas de registro. No es una decisión. Es un aplazamiento. La lámpara zumba.' }, next: 'end' },
        knock: { who: 'narr', text: { en: 'Two knocks. A chair scrapes on the other side. Then, slowly, something slides out under the door. A photograph. This desk, this lamp, you. Taken tonight.', ru: 'Два удара. С той стороны скрипит стул. Потом, медленно, из-под двери выезжает что-то. Фотография. Эта стойка, эта лампа, вы. Снято сегодня ночью.', uk: 'Два стуки. З того боку рипить стілець. Потім, повільно, з-під дверей висувається щось. Фотографія. Ця стійка, ця лампа, ви. Знято сьогодні вночі.', es: 'Dos golpes. Al otro lado se arrastra una silla. Luego, despacio, algo asoma por debajo de la puerta. Una fotografía. Este mostrador, esta lámpara, usted. Tomada esta noche.' }, next: 'end' },
        listen: { who: 'narr', text: { en: 'A kettle. A radio turned down to almost nothing. Whoever is in there is not in a hurry. You go down without knocking.', ru: 'Чайник. Радио, приглушённое почти до нуля. Кто бы там ни был, он не спешит. Вы спускаетесь, не постучав.', uk: 'Чайник. Радіо, приглушене майже до нуля. Хто б там не був, він не поспішає. Ви спускаєтеся, не постукавши.', es: 'Una tetera. Una radio con el volumen casi a cero. Quien esté ahí dentro no tiene prisa. Usted baja sin llamar.' }, next: 'end' },
        back: { who: 'narr', text: { en: "'There is no room twelve.' You say it to the stairwell. The stairwell does not agree.", ru: '«Двенадцатого номера нет». Вы говорите это лестнице. Лестница не соглашается.', uk: '«Дванадцятого номера немає». Ви кажете це сходам. Сходи не погоджуються.', es: '«No hay habitación doce». Se lo dice al hueco de la escalera. El hueco de la escalera no está de acuerdo.' }, next: 'end' },
      }
    },
    {
      name: { en: 'Denis', ru: 'Денис', uk: 'Денис', es: 'Denis' }, voice: { gender: 'm', pitch: 0.9, rate: 0.85 },
      portrait: portrait('#6a6a7a', false, false), start: 'a',
      when: (s) => s.flags.went_up,
      nodes: {
        a: { who: 'narr', effect: { flags: { met_denis: true } },
             text: { en: 'A room bigger than the floor plan allows. A bed. A kettle. A desk exactly like yours, lamp and all. And a wall of photographs.', ru: 'Комната больше, чем позволяет план этажа. Кровать. Чайник. Стойка точь-в-точь как ваша, вместе с лампой. И стена фотографий.', uk: 'Кімната більша, ніж дозволяє план поверху. Ліжко. Чайник. Стійка точнісінько як ваша, разом із лампою. І стіна фотографій.', es: 'Una habitación más grande de lo que permite el plano. Una cama. Una tetera. Un mostrador idéntico al suyo, lámpara incluida. Y una pared de fotografías.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.thursday
              ? { en: "You came. Before Friday. You're the first one who asked what Friday was before coming up. …Sit. The kettle's just gone; the locks haven't.", ru: 'Вы пришли. До пятницы. Вы {первый|первая}, кто спросил, что такое пятница, прежде чем подняться. …Садитесь. Чайник только что вскипел; замки ещё не сменили.', uk: 'Ви прийшли. До п’ятниці. Ви {перший|перша}, хто спитав, що таке п’ятниця, перш ніж піднятися. …Сідайте. Чайник щойно закипів; замки ще не змінили.', es: 'Ha venido. Antes del viernes. Es {el primero|la primera} que preguntó qué era el viernes antes de subir. …Siéntese. El agua acaba de hervir; las cerraduras todavía no han cambiado.' }
              : s.flags.denis_call
              ? { en: "You came. Before Friday. …I wasn't sure you'd heard me. Sit. The kettle's just gone.", ru: 'Вы пришли. До пятницы. …Я не был уверен, что вы меня расслышали. Садитесь. Чайник только что вскипел.', uk: 'Ви прийшли. До п’ятниці. …Я не був певен, що ви мене почули. Сідайте. Чайник щойно закипів.', es: 'Ha venido. Antes del viernes. …No estaba seguro de que me hubiera oído. Siéntese. El agua acaba de hervir.' }
              : { en: "You're the new one. I'd know you anywhere; you're on the wall. Sit. The kettle's just gone.", ru: 'Вы новая смена. Я бы вас везде узнал: вы на стене. Садитесь. Чайник только что вскипел.', uk: 'Ви нова зміна. Я б вас упізнав де завгодно: ви на стіні. Сідайте. Чайник щойно закипів.', es: 'Usted es {el nuevo|la nueva}. {Lo|La} reconocería en cualquier parte; está en la pared. Siéntese. El agua acaba de hervir.' },
             next: 'c' },
        c: { who: 'narr', text: { en: 'He is younger than you expected and calmer than anyone should be. He pours two cups. He does not ask why you came.', ru: 'Он моложе, чем вы ожидали, и спокойнее, чем положено человеку. Наливает две чашки. Не спрашивает, зачем вы пришли.', uk: 'Він молодший, ніж ви очікували, і спокійніший, ніж годиться людині. Наливає дві чашки. Не питає, навіщо ви прийшли.', es: 'Es más joven de lo que usted esperaba y está más tranquilo de lo que nadie debería estar. Sirve dos tazas. No pregunta por qué ha venido.' },
             choices: [
               { text: { en: '"Marv thinks you\'re dead."', ru: '«Марв думает, что вы погибли».', uk: '«Марв думає, що ви загинули».', es: '«Marv cree que usted está muerto».' }, next: 'marv' },
               { text: { en: '"What is this room?"', ru: '«Что это за комната?»', uk: '«Що це за кімната?»', es: '«¿Qué es esta habitación?»' }, next: 'what' },
               { text: { en: '"Get your coat. We\'re leaving."', ru: '«Берите пальто. Мы уходим».', uk: '«Беріть пальто. Ми йдемо».', es: '«Póngase el abrigo. Nos vamos».' }, next: 'leave' },
             ] },
        marv: { who: 'guest', text: { en: "Marv. …Tell him I'm all right. Don't tell him where. He'd come up, and then there'd be a Marv on the wall.", ru: 'Марв. …Скажите ему, что я в порядке. Не говорите где. Он поднимется, и тогда на стене появится Марв.', uk: 'Марв. …Скажіть йому, що я в порядку. Не кажіть де. Він підніметься, і тоді на стіні з’явиться Марв.', es: 'Marv. …Dígale que estoy bien. No le diga dónde. Subiría, y entonces habría un Marv en la pared.' }, next: 'wall' },
        what: { who: 'guest', text: { en: "A room where things wait. Some nights a suitcase. Some nights a person. I make tea and don't ask. I was a night clerk. It's not so different.", ru: 'Комната, где вещи ждут. Иногда чемодан. Иногда человек. Я завариваю чай и не спрашиваю. Я был ночным портье. Не такая уж разница.', uk: 'Кімната, де речі чекають. Іноді валіза. Іноді людина. Я заварюю чай і не питаю. Я був нічним портьє. Не така вже й різниця.', es: 'Una habitación donde las cosas esperan. Unas noches, una maleta. Otras, una persona. Yo preparo té y no pregunto. Fui recepcionista de noche. No es tan distinto.' }, next: 'wall' },
        leave: { who: 'guest', text: { en: "I haven't got a coat. He took it the first night; it's in one of the pictures. Sit down. Look at the wall first. Then tell me where I'd go.", ru: 'У меня нет пальто. Он забрал его в первую ночь; оно на одной из фотографий. Сядьте. Сначала посмотрите на стену. Потом скажите, куда мне идти.', uk: 'У мене немає пальта. Він забрав його першої ночі; воно на одній із фотографій. Сядьте. Спочатку подивіться на стіну. Потім скажіть, куди мені йти.', es: 'No tengo abrigo. Se lo quedó él la primera noche; sale en una de las fotos. Siéntese. Mire primero la pared. Luego dígame adónde iría yo.' }, next: 'wall' },
        wall: { who: 'narr', text: { en: 'Photographs, floor to ceiling. Night clerks behind desks, under different lamps, in different cities. Some are yellow with age. The newest is you, still curling at the corners.', ru: 'Фотографии от пола до потолка. Ночные портье за стойками, под разными лампами, в разных городах. Некоторые пожелтели. Самая новая — вы, ещё загибается по углам.', uk: 'Фотографії від підлоги до стелі. Нічні портьє за стійками, під різними лампами, в різних містах. Деякі пожовкли. Найновіша — ви, ще загинається по кутах.', es: 'Fotografías, del suelo al techo. Recepcionistas de noche tras sus mostradores, bajo lámparas distintas, en ciudades distintas. Algunas, amarillas de viejas. La más nueva es usted, todavía con las esquinas curvadas.' }, next: 'wall2' },
        wall2: { who: 'guest', text: { en: "Every small hotel has a room like this. Every room had a clerk who said yes. I keep the pictures so somebody knows who. He calls it the register.", ru: 'В каждом маленьком отеле есть такая комната. В каждой комнате был портье, который сказал «да». Я храню снимки, чтобы кто-то знал, кто именно. Он называет это реестром.', uk: 'У кожному маленькому готелі є така кімната. У кожній кімнаті був портьє, який сказав «так». Я зберігаю знімки, щоб хтось знав, хто саме. Він називає це реєстром.', es: 'Cada hotel pequeño tiene una habitación así. Cada habitación tuvo un recepcionista que dijo que sí. Yo guardo las fotos para que alguien sepa quién. Él lo llama el registro.' },
                choices: [
                  { text: { en: '"Help me end this. All of it."', ru: '«Помогите мне это закончить. Всё это».', uk: '«Допоможіть мені це закінчити. Усе це».', es: '«Ayúdeme a acabar con esto. Con todo».' }, next: 'ally', effect: { flags: { denis_ally: true } } },
                  { text: { en: '"The door isn\'t even locked. You could walk out."', ru: '«Дверь даже не заперта. Вы могли бы просто выйти».', uk: '«Двері навіть не замкнені. Ви могли б просто вийти».', es: '«La puerta ni siquiera está cerrada con llave. Podría irse andando».' }, next: 'stays', effect: { flags: { denis_stays: true } } },
                  { text: { en: '"I\'m going back down. Alone."', ru: '«Я возвращаюсь вниз. Без вас».', uk: '«Я повертаюся вниз. Без вас».', es: '«Vuelvo abajo. {Solo|Sola}».' }, next: 'alone', effect: { flags: { denis_stays: true } } },
                ] },
        ally: { who: 'guest', text: { en: "…Yes. But not by leaving. I'm the only part of this anyone could put in a report. Take the wall. Leave me on it. Come back when it's done.", ru: '…Да. Но не уходом. Я единственное здесь, что можно вписать в протокол. Забирайте стену. Меня на ней оставьте. Вернётесь, когда всё закончится.', uk: '…Так. Але не втечею. Я єдине тут, що можна вписати в протокол. Забирайте стіну. Мене на ній лишіть. Повернетеся, коли все скінчиться.', es: '…Sí. Pero no marchándome. Soy lo único de todo esto que alguien podría poner en un informe. Llévese la pared. Déjeme a mí en ella. Vuelva cuando haya terminado.' }, next: 'photos' },
        stays: { who: 'guest', text: { en: "I tried, the second month. Got as far as the lobby. Sal looked at me like a bill he'd already paid. I came back up. I didn't choose this. Then I did.", ru: 'Я пробовал, на второй месяц. Дошёл до холла. Сэл посмотрел на меня как на счёт, который уже оплатил. Я вернулся наверх. Я этого не выбирал. А потом выбрал.', uk: 'Я пробував, на другий місяць. Дійшов до холу. Сел подивився на мене як на рахунок, який уже оплатив. Я повернувся нагору. Я цього не обирав. А потім обрав.', es: 'Lo intenté, el segundo mes. Llegué hasta el vestíbulo. Sal me miró como a una factura ya pagada. Volví a subir. Yo no elegí esto. Luego sí.' }, next: 'photos' },
        alone: { who: 'guest', text: { en: "That's the right answer. It's the one I should have given. …Take something with you, then. Nobody comes up here twice.", ru: 'Это правильный ответ. Его должен был дать я. …Тогда возьмите что-нибудь с собой. Сюда не поднимаются дважды.', uk: 'Це правильна відповідь. Її мав дати я. …Тоді візьміть щось із собою. Сюди не підіймаються двічі.', es: 'Esa es la respuesta correcta. La que debí dar yo. …Entonces llévese algo. Nadie sube aquí dos veces.' }, next: 'photos' },
        photos: { who: 'narr', text: { en: 'The wall waits. Some of the photographs are held by a single pin.', ru: 'Стена ждёт. Некоторые фотографии держатся на одной кнопке.', uk: 'Стіна чекає. Деякі фотографії тримаються на одній кнопці.', es: 'La pared espera. A algunas fotografías las sujeta una sola chincheta.' },
                  choices: [
                    { text: { en: 'Take the photographs. As many as fit in your coat.', ru: 'Забрать фотографии. Сколько влезет в карманы.', uk: 'Забрати фотографії. Скільки влізе в кишені.', es: 'Llevarse las fotografías. Todas las que quepan en el abrigo.' }, next: 'took', effect: { flags: { took_photos: true } } },
                    { text: { en: 'Leave the wall as it is.', ru: 'Оставить стену как есть.', uk: 'Лишити стіну як є.', es: 'Dejar la pared como está.' }, next: 'leftwall' },
                  ] },
        took: { who: 'guest', text: { en: "He counts them. He'll know by morning. …Take mine too. I'd like to be somewhere that isn't here.", ru: 'Он их считает. К утру будет знать. …Возьмите и мою. Хочется побыть где-нибудь не здесь.', uk: 'Він їх рахує. До ранку знатиме. …Візьміть і мою. Хочеться побути десь не тут.', es: 'Él las cuenta. Lo sabrá por la mañana. …Llévese también la mía. Me gustaría estar en algún sitio que no sea este.' }, next: 'took2' },
        took2: { who: 'narr', text: { en: "Seventeen photographs in your coat. Seventeen lamps. At the door he says: 'Count the flights on the way down. Four. Everyone says three.'", ru: 'Семнадцать фотографий в карманах. Семнадцать ламп. У двери он говорит: «Считайте пролёты, когда будете спускаться. Четыре. Все говорят, три».', uk: 'Сімнадцять фотографій у кишенях. Сімнадцять ламп. Біля дверей він каже: «Рахуйте прольоти, коли спускатиметеся. Чотири. Усі кажуть, три».', es: 'Diecisiete fotografías en el abrigo. Diecisiete lámparas. En la puerta, él dice: «Cuente los tramos al bajar. Cuatro. Todo el mundo dice tres».' }, next: 'end' },
        leftwall: { who: 'guest', text: { en: "Good. He'll still know you came; the stairs tell him. But not what you saw. …Tell Marv— no. Tell nobody. Come up again before Friday. Or don't.", ru: 'Хорошо. Он всё равно узнает, что вы приходили: лестница ему доложит. Но не узнает, что вы видели. …Скажите Марву… нет. Никому не говорите. Поднимитесь ещё раз до пятницы. Или нет.', uk: 'Добре. Він усе одно дізнається, що ви приходили: сходи йому доповідять. Але не дізнається, що ви бачили. …Скажіть Марву… ні. Нікому не кажіть. Підійміться ще раз до п’ятниці. Або ні.', es: 'Bien. Sabrá igual que vino; la escalera se lo cuenta. Pero no lo que vio. …Dígale a Marv… no. No se lo diga a nadie. Vuelva a subir antes del viernes. O no.' }, next: 'end' },
      }
    },
    {
      time: '03:00', name: { en: 'The man in the good coat', ru: 'Мужчина в хорошем пальто', uk: 'Чоловік у гарному пальті', es: 'El hombre del abrigo bueno' }, voice: { gender: 'm', pitch: 0.65, rate: 0.9 },
      portrait: portrait('#1e1e2e', true, false), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => s.flags.leo_bell
              ? { en: '03:00. The bell rings twice. Then the door. A man in a good coat. He looks at Leo the way you look at weather.', ru: '03:00. Звонок звенит дважды. Потом дверь. Мужчина в хорошем пальто. Он смотрит на Лео так, как смотрят на погоду.', uk: '03:00. Дзвінок дзвенить двічі. Потім двері. Чоловік у гарному пальті. Він дивиться на Лео так, як дивляться на погоду.', es: '03:00. El timbre suena dos veces. Luego la puerta. Un hombre con un abrigo bueno. Mira a Leo como quien mira el tiempo.' }
              : s.flags.marv_stairs
              ? { en: '03:00. Marv is asleep on the bottom stair. The man in the good coat steps over him without breaking stride.', ru: '03:00. Марв спит на нижней ступеньке. Мужчина в хорошем пальто перешагивает через него, не сбавляя шага.', uk: '03:00. Марв спить на нижній сходинці. Чоловік у гарному пальті переступає через нього, не стишуючи кроку.', es: '03:00. Marv duerme en el primer escalón. El hombre del abrigo bueno pasa por encima de él sin perder el paso.' }
              : { en: '03:00. The door opens without a sound. He knows before he reaches the desk. You can tell by how little he hurries.', ru: '03:00. Дверь открывается беззвучно. Он знает ещё до того, как дошёл до стойки. Видно по тому, как он не спешит.', uk: '03:00. Двері відчиняються беззвучно. Він знає ще до того, як дійшов до стійки. Видно з того, як він не поспішає.', es: '03:00. La puerta se abre sin ruido. Él ya lo sabe antes de llegar al mostrador. Se nota en lo poco que se apresura.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => s.flags.took_photos
              ? { en: "You went up. And you came down heavier. Seventeen, if I counted right. I counted right.", ru: 'Вы поднимались. И спустились тяжелее. Семнадцать, если я правильно посчитал. Я посчитал правильно.', uk: 'Ви підіймалися. І спустилися важчими. Сімнадцять, якщо я правильно порахував. Я порахував правильно.', es: 'Usted subió. Y bajó más {cargado|cargada}. Diecisiete, si conté bien. Conté bien.' }
              : s.flags.went_up
              ? { en: "You went up. The stairs told me before you reached the second floor. …How is he?", ru: 'Вы поднимались. Лестница доложила мне раньше, чем вы дошли до второго этажа. …Как он?', uk: 'Ви підіймалися. Сходи доповіли мені раніше, ніж ви дійшли до другого поверху. …Як він?', es: 'Usted subió. La escalera me avisó antes de que llegara al segundo piso. …¿Cómo está él?' }
              : s.flags.stayed_down
              ? { en: "The key in your pocket has been warm all night. You didn't use it. Denis used his the first night. …You're better at this than he was.", ru: 'Ключ в вашем кармане грелся всю ночь. Вы им не воспользовались. Денис своим воспользовался в первую же ночь. …У вас это выходит лучше, чем у него.', uk: 'Ключ у вашій кишені грівся всю ніч. Ви ним не скористалися. Денис своїм скористався першої ж ночі. …У вас це виходить краще, ніж у нього.', es: 'La llave de su bolsillo ha estado caliente toda la noche. No la usó. Denis usó la suya la primera noche. …A usted esto se le da mejor que a él.' }
              : { en: "You were at the door. Without a key. That takes a kind of nerve I don't pay for. …There is no room twelve. Say it.", ru: 'Вы были у двери. Без ключа. За такую смелость я не плачу. …Двенадцатого номера нет. Скажите это.', uk: 'Ви були біля дверей. Без ключа. За таку сміливість я не плачу. …Дванадцятого номера немає. Скажіть це.', es: 'Estuvo en la puerta. Sin llave. Eso requiere un tipo de valor que yo no pago. …No hay habitación doce. Dígalo.' },
             choices: (s) => s.flags.took_photos
              ? [
                  { text: { en: 'Hand the photographs over.', ru: 'Отдать фотографии.', uk: 'Віддати фотографії.', es: 'Entregar las fotografías.' }, next: 'handed', effect: { cash: 300, flags: { took_photos: false } } },
                  { text: { en: '"They\'re going somewhere you can\'t count them."', ru: '«Они отправятся туда, где вы их не пересчитаете».', uk: '«Вони підуть туди, де ви їх не перерахуєте».', es: '«Van a ir a algún sitio donde usted no pueda contarlas».' }, next: 'defy', effect: { trouble: 2 } },
                  { text: { en: '"He\'s fine. He asked me to tell you he\'s fine."', ru: '«Он в порядке. Просил передать, что в порядке».', uk: '«Він у порядку. Просив передати, що в порядку».', es: '«Está bien. Me pidió que le dijera que está bien».' }, next: 'fine' },
                ]
              : s.flags.went_up
              ? [
                  { text: { en: '"He\'s alive. You let Marv think he was dead."', ru: '«Он жив. Вы позволили Марву думать, что он погиб».', uk: '«Він живий. Ви дозволили Марву думати, що він загинув».', es: '«Está vivo. Dejó que Marv creyera que había muerto».' }, next: 'alive', effect: { trouble: 1 } },
                  { text: { en: '"He makes good tea."', ru: '«Он хорошо заваривает чай».', uk: '«Він добре заварює чай».', es: '«Hace buen té».' }, next: 'tea' },
                  { text: { en: '"I\'m taking this to Reyes."', ru: '«Я иду с этим к Рейес».', uk: '«Я йду з цим до Реєс».', es: '«Voy a llevarle esto a Reyes».' }, next: 'reyes', effect: { trouble: 2 } },
                ]
              : s.flags.stayed_down
              ? [
                  { text: { en: '"I\'m not Denis."', ru: '«Я не Денис».', uk: '«Я не Денис».', es: '«No soy Denis».' }, next: 'notdenis' },
                  { text: { en: '"Make it worth staying down."', ru: '«Сделайте так, чтобы оставаться внизу стоило того».', uk: '«Зробіть так, щоб лишатися внизу було варто».', es: '«Haga que quedarme abajo valga la pena».' }, next: 'paid', effect: { cash: 300 } },
                  { text: { en: '"Tomorrow I go up."', ru: '«Завтра я поднимусь».', uk: '«Завтра я підіймуся».', es: '«Mañana subo».' }, next: 'tomorrow', effect: { trouble: 1 } },
                ]
              : [
                  { text: { en: '"There is no room twelve."', ru: '«Двенадцатого номера нет».', uk: '«Дванадцятого номера немає».', es: '«No hay habitación doce».' }, next: 'said', effect: { cash: 200 } },
                  { text: { en: '"There\'s someone up there. A kettle was going."', ru: '«Там кто-то есть. Там свистел чайник».', uk: '«Там хтось є. Там свистів чайник».', es: '«Hay alguien ahí arriba. Había una tetera al fuego».' }, next: 'kettle', effect: { trouble: 1 } },
                  { text: { en: '"I\'d like a key."', ru: '«Я хочу ключ».', uk: '«Я хочу ключ».', es: '«Quisiera una llave».' }, next: 'askkey' },
                ] },
        handed: { who: 'guest', text: { en: "Three hundred. For the silence, not the pictures. …He'll have them back on the wall by morning. He's very tidy.", ru: 'Триста. За молчание, не за снимки. …К утру он развесит их обратно. Он очень аккуратный.', uk: 'Триста. За мовчання, не за знімки. …До ранку він розвісить їх назад. Він дуже акуратний.', es: 'Trescientos. Por el silencio, no por las fotos. …Por la mañana él ya las habrá vuelto a colgar. Es muy ordenado.' }, next: 'end' },
        defy: { who: 'guest', text: { en: "Somewhere I can't count. …Reyes counts for me, clerk. So does Sal. Go on. Find somewhere.", ru: 'Туда, где я не пересчитаю. …Рейес считает за меня, портье. Сэл тоже. Ну, ищите. Ищите такое место.', uk: 'Туди, де я не перерахую. …Реєс рахує за мене, портьє. Сел теж. Ну, шукайте. Шукайте таке місце.', es: 'Donde yo no pueda contarlas. …Reyes cuenta por mí, recepcionista. Sal también. Adelante. Busque ese sitio.' }, next: 'end' },
        fine: { who: 'guest', text: { en: "He is. He always is. That's what the room is for. …Keep them tonight. Tomorrow I'll want to know where they are.", ru: 'В порядке. Он всегда в порядке. Для этого и нужна комната. …Оставьте их себе на сегодня. Завтра я захочу знать, где они.', uk: 'У порядку. Він завжди в порядку. Для цього й потрібна кімната. …Лишіть їх собі на сьогодні. Завтра я захочу знати, де вони.', es: 'Lo está. Siempre lo está. Para eso es la habitación. …Quédeselas esta noche. Mañana querré saber dónde están.' }, next: 'end' },
        alive: { who: 'guest', text: { en: "Alive is the arrangement. Dead would be cheaper. Marv thinks what Marv needs to think.", ru: 'Жив — таков уговор. Мёртвый обошёлся бы дешевле. Марв думает то, что ему нужно думать.', uk: 'Живий — така домовленість. Мертвий обійшовся б дешевше. Марв думає те, що йому треба думати.', es: 'Vivo es el acuerdo. Muerto saldría más barato. Marv piensa lo que Marv necesita pensar.' }, next: 'end' },
        tea: { who: 'guest', text: { en: "He does. …They all come down from there a different clerk. I'm curious which one you'll be.", ru: 'Да, хорошо. …Оттуда все спускаются другими портье. Мне любопытно, кем окажетесь вы.', uk: 'Так, добре. …Звідти всі спускаються іншими портьє. Мені цікаво, ким виявитеся ви.', es: 'Sí que lo hace. …Todos bajan de ahí convertidos en otra persona. Tengo curiosidad por ver en cuál se convierte usted.' }, next: 'end' },
        reyes: { who: 'guest', text: { en: "Reyes. …Yes. Do that. She has a desk too. It's just further from the stairs.", ru: 'Рейес. …Да. Идите. У неё тоже есть стойка. Просто она дальше от лестницы.', uk: 'Реєс. …Так. Ідіть. У неї теж є стійка. Просто вона далі від сходів.', es: 'Reyes. …Sí. Hágalo. Ella también tiene un mostrador. Solo que está más lejos de la escalera.' }, next: 'end' },
        notdenis: { who: 'guest', text: { en: "No. Denis was curious. You're careful. I have more use for careful. …Good night, clerk.", ru: 'Нет. Денис был любопытен. Вы осторожны. Осторожность мне полезнее. …Спокойной ночи, портье.', uk: 'Ні. Денис був допитливий. Ви обережні. Обережність мені корисніша. …Добраніч, портьє.', es: 'No. Denis era curioso. Usted es prudente. La prudencia me sirve más. …Buenas noches, recepcionista.' }, next: 'end' },
        paid: { who: 'guest', text: { en: "Three hundred. For the flights you didn't climb. It's the same rate either way; that's what nobody understands.", ru: 'Триста. За пролёты, по которым вы не поднялись. Ставка одна в обе стороны; этого никто не понимает.', uk: 'Триста. За прольоти, якими ви не піднялися. Ставка одна в обидва боки; цього ніхто не розуміє.', es: 'Trescientos. Por los tramos que no subió. La tarifa es la misma en los dos sentidos; eso es lo que nadie entiende.' }, next: 'end' },
        tomorrow: { who: 'guest', text: { en: "Tomorrow is Friday. …Then tomorrow. I'll leave the light on.", ru: 'Завтра пятница. …Значит, завтра. Я оставлю свет.', uk: 'Завтра п’ятниця. …Отже, завтра. Я лишу світло.', es: 'Mañana es viernes. …Entonces, mañana. Dejaré la luz encendida.' }, next: 'end' },
        said: { who: 'guest', text: { en: "Good. Two hundred for the pronunciation. It gets harder every night. That's how I know it's working.", ru: 'Хорошо. Двести за произношение. С каждой ночью выговаривать труднее. По этому я и понимаю, что всё работает.', uk: 'Добре. Двісті за вимову. З кожною ніччю вимовляти важче. З цього я й розумію, що все працює.', es: 'Bien. Doscientos por la pronunciación. Cada noche cuesta más. Así sé que funciona.' }, next: 'end' },
        kettle: { who: 'guest', text: { en: "A kettle. …You have good ears, clerk. Keep them. Ears are harder to replace than clerks.", ru: 'Чайник. …У вас хороший слух, портье. Берегите его. Слух заменить труднее, чем портье.', uk: 'Чайник. …У вас добрий слух, портьє. Бережіть його. Слух замінити важче, ніж портьє.', es: 'Una tetera. …Tiene buen oído, recepcionista. Cuídelo. Un oído es más difícil de reemplazar que un recepcionista.' }, next: 'end' },
        askkey: { who: 'guest', text: { en: "Would you. Denis asked. Look how well that went for Denis. …No. Not yet. Ask me on Friday.", ru: 'Вот как. Денис тоже просил. Посмотрите, как это вышло Денису. …Нет. Пока нет. Спросите в пятницу.', uk: 'Он як. Денис теж просив. Подивіться, як це вийшло Денисові. …Ні. Поки ні. Спитайте в п’ятницю.', es: '¿Ah, sí? Denis también la pidió. Mire lo bien que le fue a Denis. …No. Todavía no. Pídamela el viernes.' }, next: 'end' },
      }
    },
    {
      time: '05:00', name: { en: 'Officer Reyes', ru: 'Офицер Рейес', uk: 'Офіцер Реєс', es: 'Agente Reyes' }, voice: { gender: 'f', pitch: 0.95, rate: 1.0 },
      portrait: portrait('#2a3a6a', true, false), start: 'a',
      nodes: {
        a: { who: 'narr', text: (s) => (s.flags.tracker && !s.flags.envelope)
              ? { en: '05:00. Reyes. She puts her phone on the desk, screen up. A map. One dot. This building.', ru: '05:00. Рейес. Она кладёт телефон на стойку экраном вверх. Карта. Одна точка. Это здание.', uk: '05:00. Реєс. Вона кладе телефон на стійку екраном догори. Мапа. Одна точка. Ця будівля.', es: '05:00. Reyes. Deja el teléfono en el mostrador, con la pantalla hacia arriba. Un mapa. Un punto. Este edificio.' }
              : { en: '05:00. Reyes. She has not slept; you can tell by how carefully she sets the coffee down.', ru: '05:00. Рейес. Она не спала; видно по тому, как осторожно она ставит кофе.', uk: '05:00. Реєс. Вона не спала; видно з того, як обережно вона ставить каву.', es: '05:00. Reyes. No ha dormido; se nota por el cuidado con que deja el café.' },
             next: 'b' },
        b: { who: 'guest', text: (s) => (s.flags.tracker && !s.flags.envelope)
              ? { en: "It went up. Not out. Four flights, and it hasn't moved in twenty hours. Room twelve is in this hotel. Three years I've stood outside the wrong buildings. …Whose side are you on? Say it.", ru: 'Он ушёл наверх. Не на улицу. Четыре пролёта, и двадцать часов не двигается. Двенадцатый номер в этом отеле. Три года я стояла не у тех зданий. …На чьей вы стороне? Скажите.', uk: 'Він пішов нагору. Не на вулицю. Чотири прольоти, і двадцять годин не рухається. Дванадцятий номер у цьому готелі. Три роки я стояла не біля тих будівель. …На чиєму ви боці? Скажіть.', es: 'Subió. No salió. Cuatro tramos, y lleva veinte horas sin moverse. La habitación doce está en este hotel. Tres años plantada delante de los edificios equivocados. …¿De qué lado está usted? Dígalo.' }
              : s.flags.went_up
              ? { en: "You went up. It's on your face; they all come down with that face. …I'm not asking as a cop. Whose side are you on?", ru: 'Вы поднимались. Это у вас на лице; все спускаются с таким лицом. …Я спрашиваю не как полицейская. На чьей вы стороне?', uk: 'Ви підіймалися. Це у вас на обличчі; усі спускаються з таким обличчям. …Я питаю не як поліцейська. На чиєму ви боці?', es: 'Usted subió. Lo lleva en la cara; todos bajan con esa cara. …No se lo pregunto como policía. ¿De qué lado está?' }
              : { en: "Nothing to report? Good. Neither have I. Three years of nothing. …I'm going to ask you something I'm not supposed to. Whose side of that desk are you on?", ru: 'Докладывать нечего? Хорошо. Мне тоже. Три года ничего. …Я спрошу то, что не должна спрашивать. На чьей стороне этой стойки вы стоите?', uk: 'Доповідати нічого? Добре. Мені теж. Три роки нічого. …Я спитаю те, чого не повинна питати. На чиєму боці цієї стійки ви стоїте?', es: '¿Nada que informar? Bien. Yo tampoco. Tres años de nada. …Voy a preguntarle algo que no debería. ¿De qué lado de ese mostrador está usted?' },
             choices: (s) => s.flags.took_photos
              ? [
                  { text: { en: 'Put the photographs on the desk.', ru: 'Выложить фотографии на стойку.', uk: 'Викласти фотографії на стійку.', es: 'Poner las fotografías sobre el mostrador.' }, next: 'show', effect: { flags: { reyes_side: true } } },
                  { text: { en: '"His. It\'s safer, and you know it is."', ru: '«На его. Так безопаснее, и вы это знаете».', uk: '«На його. Так безпечніше, і ви це знаєте».', es: '«Del lado de él. Es más seguro, y usted lo sabe».' }, next: 'his', effect: { flags: { man_side: true } } },
                  { text: { en: "Don't answer.", ru: 'Не отвечать.', uk: 'Не відповідати.', es: 'No responder.' }, next: 'quiet' },
                ]
              : s.flags.knows_reyes
              ? [
                  { text: { en: '"Yours."', ru: '«На вашей».', uk: '«На вашому».', es: '«Del suyo».' }, next: 'yours', effect: { flags: { reyes_side: true } } },
                  { text: { en: '"His. It\'s safer, and you know it is."', ru: '«На его. Так безопаснее, и вы это знаете».', uk: '«На його. Так безпечніше, і ви це знаєте».', es: '«Del lado de él. Es más seguro, y usted lo sabe».' }, next: 'his', effect: { flags: { man_side: true } } },
                  { text: { en: '"You\'re on his payroll. Strange question."', ru: '«Вы у него на зарплате. Странный вопрос».', uk: '«Ви в нього на зарплаті. Дивне запитання».', es: '«Usted cobra de él. Qué pregunta tan rara».' }, next: 'strange', effect: { trouble: 1 } },
                ]
              : [
                  { text: { en: '"Yours."', ru: '«На вашей».', uk: '«На вашому».', es: '«Del suyo».' }, next: 'yours', effect: { flags: { reyes_side: true } } },
                  { text: { en: '"His. It\'s safer, and you know it is."', ru: '«На его. Так безопаснее, и вы это знаете».', uk: '«На його. Так безпечніше, і ви це знаєте».', es: '«Del lado de él. Es más seguro, y usted lo sabe».' }, next: 'his', effect: { flags: { man_side: true } } },
                  { text: { en: "Don't answer.", ru: 'Не отвечать.', uk: 'Не відповідати.', es: 'No responder.' }, next: 'quiet' },
                ] },
        yours: { who: 'guest', text: { en: "…Don't say it like that. Say it like it costs something. It will.", ru: '…Не говорите так. Скажите так, будто это чего-то стоит. Потому что будет стоить.', uk: '…Не кажіть так. Скажіть так, ніби це чогось коштує. Бо коштуватиме.', es: '…No lo diga así. Dígalo como si costara algo. Porque va a costar.' }, next: 'end' },
        his: { who: 'guest', text: { en: "…Yes. It is. I'm not going to write that down. I'm not going to forget it either.", ru: '…Да. Безопаснее. Я не буду это записывать. И не забуду тоже.', uk: '…Так. Безпечніше. Я не записуватиму цього. І не забуду теж.', es: '…Sí. Lo es. No voy a apuntarlo. Tampoco voy a olvidarlo.' }, next: 'end' },
        quiet: { who: 'guest', text: { en: "That's an answer too. It's his. It just doesn't know it yet.", ru: 'Это тоже ответ. И он в его пользу. Просто пока сам об этом не знает.', uk: 'Це теж відповідь. І вона на його користь. Просто поки сама про це не знає.', es: 'Eso también es una respuesta. Es de él. Solo que todavía no lo sabe.' }, next: 'end' },
        show: { who: 'guest', text: { en: "Put them away. Not here. Not to me. …If you'd handed me those, they'd be in his coat by noon. I'm telling you that. Think about what it means that I'm telling you.", ru: 'Уберите. Не здесь. Не мне. …Отдали бы мне — к полудню они были бы у него в пальто. Я вам это говорю. Подумайте, что значит, что это говорю я.', uk: 'Сховайте. Не тут. Не мені. …Віддали б мені — до полудня вони були б у нього в пальті. Я вам це кажу. Подумайте, що означає, що це кажу я.', es: 'Guárdelas. Aquí no. A mí no. …Si me las hubiera dado, a mediodía estarían en el abrigo de él. Se lo estoy diciendo yo. Piense en lo que significa que se lo diga yo.' }, next: 'end' },
        strange: { who: 'guest', text: { en: "It is strange. I've been strange for three years. …I'm still asking.", ru: 'Странный. Я странная уже три года. …И всё равно спрашиваю.', uk: 'Дивне. Я дивна вже три роки. …І все одно питаю.', es: 'Lo es. Llevo tres años siendo rara. …Y sigo preguntando.' },
                   choices: [
                     { text: { en: '"Yours."', ru: '«На вашей».', uk: '«На вашому».', es: '«Del suyo».' }, next: 'yours', effect: { flags: { reyes_side: true } } },
                     { text: { en: '"His."', ru: '«На его».', uk: '«На його».', es: '«Del lado de él».' }, next: 'his', effect: { flags: { man_side: true } } },
                   ] },
      }
    },
    {
      time: '06:00', name: { en: 'Sal (the manager)', ru: 'Сэл (управляющий)', uk: 'Сел (управитель)', es: 'Sal (el gerente)' }, voice: { gender: 'm', pitch: 0.7, rate: 1.05 },
      portrait: portrait('#7a2a2a', false, true), start: 'a',
      nodes: {
        a: { who: 'guest', text: (s) => s.flags.went_up
              ? { en: "Morning. …You went up. Don't. I don't want to— …Is he all right?", ru: 'Утро. …Значит, наверх. Не надо. Я не хочу… …Он в порядке?', uk: 'Ранок. …Отже, нагору. Не треба. Я не хочу… …Він у порядку?', es: 'Buenos días. …Subiste. No me lo cuentes. No quiero… …¿Él está bien?' }
              : s.flags.stayed_down
              ? { en: "Morning. Register. …And whatever's in your pocket, put it back where it was before he decides you're keeping it.", ru: 'Утро. Касса. …И что бы там ни лежало у тебя в кармане, положи на место, пока он не решил, что ты это оставляешь себе.', uk: 'Ранок. Каса. …І що б там не лежало в тебе в кишені, поклади на місце, поки він не вирішив, що ти лишаєш це собі.', es: 'Buenos días. La caja. …Y lo que sea que tengas en el bolsillo, devuélvelo a su sitio antes de que él decida que te lo quedas.' }
              : { en: "Morning. Register. Marv says you were on the stairs. There's nothing up there. There's never been anything up there. That's the job.", ru: 'Утро. Касса. Марв говорит, тебя видели на лестнице. Там ничего нет. Там никогда ничего не было. В этом и работа.', uk: 'Ранок. Каса. Марв каже, тебе бачили на сходах. Там нічого немає. Там ніколи нічого не було. У цьому й робота.', es: 'Buenos días. La caja. Marv dice que estuviste en la escalera. Ahí arriba no hay nada. Nunca ha habido nada. En eso consiste el trabajo.' },
             choices: (s) => s.flags.went_up
              ? [
                  { text: { en: '"He\'s alive. He makes tea."', ru: '«Он жив. Заваривает чай».', uk: '«Він живий. Заварює чай».', es: '«Está vivo. Hace té».' }, next: 'ok' },
                  { text: { en: '"You\'ve always known."', ru: '«Вы всегда знали».', uk: '«Ви завжди знали».', es: '«Usted siempre lo ha sabido».' }, next: 'knew', effect: { trouble: 1 } },
                ]
              : undefined,
             next: 'end' },
        ok: { who: 'guest', text: { en: "…Tea. Right. …He always did make it too strong. Register.", ru: '…Чай. Ясно. …Он всегда заваривал слишком крепко. Касса.', uk: '…Чай. Ясно. …Він завжди заварював надто міцно. Каса.', es: '…Té. Ya. …Siempre lo hacía demasiado cargado. La caja.' }, next: 'end' },
        knew: { who: 'guest', text: (s) => s.flags.sal_cut
              ? { en: "I take a cut. I told you that. That's the whole confession, and I'm not making it twice. Register.", ru: 'Я беру долю. Я это говорил. Вот и всё признание, и дважды я его не делаю. Касса.', uk: 'Я беру частку. Я це казав. Ось і все зізнання, і двічі я його не роблю. Каса.', es: 'Me llevo una parte. Ya te lo dije. Esa es toda la confesión, y no pienso repetirla. La caja.' }
              : { en: "I've always known there's a floor I don't go to. That is not the same as knowing. …Don't say that word to me again. Register.", ru: 'Я всегда знал, что есть этаж, на который я не хожу. Это не то же самое, что знать. …Больше не говори мне этого слова. Касса.', uk: 'Я завжди знав, що є поверх, на який я не ходжу. Це не те саме, що знати. …Більше не кажи мені цього слова. Каса.', es: 'Siempre he sabido que hay un piso al que no voy. No es lo mismo que saber. …No vuelvas a decirme esa palabra. La caja.' },
               next: 'end' },
      }
    },
  ],
  pickEnding(state) {
    const f = state.flags;
    if (state.trouble >= TROUBLE_MAX) return 'fired';
    if (f.took_photos) return 'evidence';
    if (f.met_denis) return f.denis_ally ? 'ally' : 'keeper';
    if (f.stayed_down) return 'downstairs';
    if (f.man_side) return 'his_side';
    if (f.reyes_side) return 'her_side';
    return 'no_number';
  },
  endings: {
    fired: {
      en: ['SHIFT OVER', "A whole week's worth of trouble, and it is only Thursday; Sal does not need to hear the rest. 'Out.' The top-floor light is on as you cross the street. It goes off when you look up."],
      ru: ['СМЕНА ОКОНЧЕНА', 'Проблем набралось на целую неделю, а на дворе только четверг; остальное Сэлу слушать незачем. «Вон». Свет на верхнем этаже горит, пока вы переходите дорогу. Гаснет, когда вы поднимаете глаза.'],
      uk: ['ЗМІНУ ЗАКІНЧЕНО', 'Проблем назбиралося на цілий тиждень, а надворі лише четвер; решту Селові слухати нема чого. «Геть». Світло на верхньому поверсі горить, поки ви переходите дорогу. Гасне, коли ви підводите очі.'],
      es: ['FIN DEL TURNO', 'Problemas para una semana entera, y apenas es jueves; Sal no necesita oír el resto. «Fuera». La luz del último piso está encendida mientras usted cruza la calle. Se apaga cuando levanta la vista.'] },
    evidence: {
      en: ['EVIDENCE', "Seventeen photographs in your coat. Seventeen night clerks under seventeen lamps, and one of them is you. He counted. So did you. Tomorrow one of you does something about it."],
      ru: ['УЛИКИ', 'Семнадцать фотографий в карманах. Семнадцать ночных портье под семнадцатью лампами, и {один|одна} из них — вы. Он посчитал. Вы тоже. Завтра кто-то из вас что-то с этим сделает.'],
      uk: ['ДОКАЗИ', 'Сімнадцять фотографій у кишенях. Сімнадцять нічних портьє під сімнадцятьма лампами, і {один|одна} із них — ви. Він порахував. Ви теж. Завтра хтось із вас щось із цим зробить.'],
      es: ['PRUEBAS', 'Diecisiete fotografías en el abrigo. Diecisiete recepcionistas de noche bajo diecisiete lámparas, y {uno|una} de ellos es usted. Él las contó. Usted también. Mañana uno de los dos hará algo al respecto.'] },
    ally: {
      en: ['BEFORE FRIDAY', "Denis stays upstairs so that someone can prove he is there. You came up before Friday. Now there is a Friday, and it has your name on it."],
      ru: ['ДО ПЯТНИЦЫ', 'Денис остаётся наверху, чтобы кто-то мог доказать, что он там есть. Вы поднялись до пятницы. Теперь пятница наступит, и на ней ваше имя.'],
      uk: ['ДО П’ЯТНИЦІ', 'Денис лишається нагорі, щоб хтось міг довести, що він там є. Ви піднялися до п’ятниці. Тепер п’ятниця настане, і на ній ваше ім’я.'],
      es: ['ANTES DEL VIERNES', 'Denis se queda arriba para que alguien pueda demostrar que está ahí. Usted subió antes del viernes. Ahora hay un viernes, y lleva su nombre.'] },
    keeper: {
      en: ['THE KEEPER', "He is alive. He makes tea. He keeps the wall. He did not choose it; then he did. You go down four flights and count every one."],
      ru: ['ХРАНИТЕЛЬ', 'Он жив. Он заваривает чай. Он хранит стену. Он этого не выбирал; а потом выбрал. Вы спускаетесь на четыре пролёта и считаете каждый.'],
      uk: ['ХРАНИТЕЛЬ', 'Він живий. Він заварює чай. Він береже стіну. Він цього не обирав; а потім обрав. Ви спускаєтеся на чотири прольоти і рахуєте кожен.'],
      es: ['EL GUARDIÁN', 'Está vivo. Prepara té. Cuida la pared. No lo eligió; luego sí. Usted baja los cuatro tramos y cuenta cada uno.'] },
    downstairs: {
      en: ['DOWNSTAIRS', "The key is back under the register cards, still warm. You did not go up. It is not a decision; it is a postponement. Tomorrow is Friday."],
      ru: ['ВНИЗУ', 'Ключ снова под карточками, ещё тёплый. Вы не поднялись. Это не решение; это отсрочка. Завтра пятница.'],
      uk: ['УНИЗУ', 'Ключ знову під картками, ще теплий. Ви не піднялися. Це не рішення; це відстрочка. Завтра п’ятниця.'],
      es: ['ABAJO', 'La llave vuelve a estar bajo las fichas de registro, todavía caliente. Usted no subió. No es una decisión; es un aplazamiento. Mañana es viernes.'] },
    his_side: {
      en: ['HIS SIDE', "You said it to a cop's face and she did not write it down. Across the street a man in a good coat nods once, as if he had heard."],
      ru: ['ЕГО СТОРОНА', 'Вы сказали это полицейской в лицо, и она не стала записывать. Через дорогу мужчина в хорошем пальто кивает один раз, будто услышал.'],
      uk: ['ЙОГО БІК', 'Ви сказали це поліцейській в обличчя, і вона не стала записувати. Через дорогу чоловік у гарному пальті киває один раз, ніби почув.'],
      es: ['CON ÉL', 'Se lo dijo a una policía a la cara y ella no lo apuntó. Al otro lado de la calle, un hombre con un abrigo bueno asiente una vez, como si lo hubiera oído.'] },
    her_side: {
      en: ['HER SIDE', "'Yours.' She took it like something heavy. Three years outside the wrong buildings; now she is inside the right one, and so are you."],
      ru: ['ЕЁ СТОРОНА', '«На вашей». Она приняла это как что-то тяжёлое. Три года не у тех зданий; теперь она внутри того самого, и вы тоже.'],
      uk: ['ЇЇ БІК', '«На вашому». Вона прийняла це як щось важке. Три роки не біля тих будівель; тепер вона всередині тієї самої, і ви теж.'],
      es: ['CON ELLA', '«Del suyo». Ella lo recibió como algo pesado. Tres años delante de los edificios equivocados; ahora está dentro del correcto, y usted también.'] },
    no_number: {
      en: ['NO NUMBER', "The door has no number and you have no key. You stood at it anyway. You still say there is no room twelve. It gets harder to pronounce."],
      ru: ['БЕЗ НОМЕРА', 'На двери нет номера, а у вас нет ключа. Вы всё равно стояли перед ней. Вы по-прежнему говорите, что двенадцатого номера нет. Выговаривать всё труднее.'],
      uk: ['БЕЗ НОМЕРА', 'На дверях немає номера, а у вас немає ключа. Ви все одно стояли перед ними. Ви й далі кажете, що дванадцятого номера немає. Вимовляти дедалі важче.'],
      es: ['SIN NÚMERO', 'La puerta no tiene número y usted no tiene llave. Aun así se quedó delante. Sigue diciendo que no hay habitación doce. Cada vez cuesta más pronunciarlo.'] },
  },
});
